sys_script_include.script:
var PopulateEmployeeDetails = Class.create();
PopulateEmployeeDetails.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getEmployeeDetails: function() {

        var userId = this.getParameter('sysparm_user');

        var grUser = new GlideRecord('sys_user');

        if (grUser.get(userId)) {

            var result = {
                name: grUser.getDisplayValue(),
                email: grUser.email.toString(),
                department: grUser.department.getDisplayValue()
            };

            return JSON.stringify(result);
        }

        return "";

    },

    type: 'PopulateEmployeeDetails'
});
